package com.fireplatform.notification;

import com.fireplatform.configuration.DatabaseTime;
import com.fireplatform.identity.*;
import com.fireplatform.shared.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.fireplatform.notification.NotificationReads.*;

@Service
public class NotificationChannelPolicyService {
    public record Effective(boolean enabled,String scopeType,String scopeId) { }
    private final JdbcTemplate jdbc;private final ExecutionAuthorization auth;private final TenantFence tenants;private final IdempotencyStore idem;private final DatabaseTime time;private final AuditService audit;private final ScopeFilter scope;
    public NotificationChannelPolicyService(JdbcTemplate jdbc,ExecutionAuthorization auth,TenantFence tenants,IdempotencyStore idem,DatabaseTime time,AuditService audit,ScopeFilter scope){this.jdbc=jdbc;this.auth=auth;this.tenants=tenants;this.idem=idem;this.time=time;this.audit=audit;this.scope=scope;}
    public Effective effectiveForDevice(String tenant,String device,String channel){var rows=jdbc.queryForList("SELECT place_id FROM devices WHERE tenant_id=? AND id=?",tenant,device);if(rows.isEmpty())return new Effective(false,"DEFAULT",null);return effective(tenant,(String)rows.getFirst().get("place_id"),channel);}
    public Effective effective(String tenant,String place,String channel){NotificationPolicy.choice(channel,List.of("SMS","VOICE","WECHAT"));String current=place;var seen=new HashSet<String>();while(current!=null&&seen.add(current)){var rows=jdbc.queryForList("SELECT parent_place_id FROM places WHERE tenant_id=? AND id=?",tenant,current);if(rows.isEmpty())break;var policy=jdbc.queryForList("SELECT "+column(channel)+" AS enabled FROM notification_channel_policies WHERE tenant_id=? AND scope_type='PLACE' AND place_id=?",tenant,current);if(!policy.isEmpty()&&policy.getFirst().get("enabled")!=null)return new Effective(Boolean.TRUE.equals(policy.getFirst().get("enabled")),"PLACE",current);current=(String)rows.getFirst().get("parent_place_id");}var unit=jdbc.queryForList("SELECT "+column(channel)+" AS enabled FROM notification_channel_policies WHERE tenant_id=? AND scope_type='UNIT'",tenant);if(!unit.isEmpty()&&unit.getFirst().get("enabled")!=null)return new Effective(Boolean.TRUE.equals(unit.getFirst().get("enabled")),"UNIT",tenant);return new Effective(false,"DEFAULT",null);}
    private static String column(String channel){return switch(channel){case "SMS"->"sms_enabled";case "VOICE"->"voice_enabled";case "WECHAT"->"wechat_enabled";default->throw ApiError.bad("通知通道无效");};}
    private static List<Object> concat(List<?> first,List<Object> second){var result=new ArrayList<Object>(first);result.addAll(second);return result;}
    public Map<String,Object> read(String actor,String tenant,String scopeType,String placeId,ScopeFilter.Selection selection){String selected=NotificationPolicy.choice(scopeType,List.of("UNIT","PLACE"));if(selected.equals("UNIT")){if(placeId!=null)throw ApiError.bad("单位策略不能指定位置");}else{if(placeId==null||placeId.isBlank())throw ApiError.bad("位置策略必须指定位置");if(jdbc.queryForList("SELECT id FROM places WHERE tenant_id=? AND id=?",tenant,placeId).isEmpty())throw ApiError.missing();}requireVisible(actor,tenant,selected,placeId,selection);var rows=jdbc.queryForList("SELECT * FROM notification_channel_policies WHERE tenant_id=? AND scope_type=? AND scope_key=?",tenant,selected,selected.equals("UNIT")?tenant:placeId);var out=new LinkedHashMap<String,Object>();out.put("tenant_id",tenant);out.put("scope_type",selected);out.put("place_id",selected.equals("PLACE")?placeId:null);out.put("configured",!rows.isEmpty());out.put("revision",rows.isEmpty()?0L:number(rows.getFirst(),"revision"));out.put("sms_enabled",rows.isEmpty()?null:rows.getFirst().get("sms_enabled"));out.put("voice_enabled",rows.isEmpty()?null:rows.getFirst().get("voice_enabled"));out.put("wechat_enabled",rows.isEmpty()?null:rows.getFirst().get("wechat_enabled"));var smsEffective=effective(tenant,selected.equals("PLACE")?placeId:null,"SMS");var voiceEffective=effective(tenant,selected.equals("PLACE")?placeId:null,"VOICE");var wechatEffective=effective(tenant,selected.equals("PLACE")?placeId:null,"WECHAT");out.put("effective_sms",smsEffective.enabled());out.put("effective_voice",voiceEffective.enabled());out.put("effective_wechat",wechatEffective.enabled());out.put("sms_source",source(tenant,smsEffective));out.put("voice_source",source(tenant,voiceEffective));out.put("wechat_source",source(tenant,wechatEffective));return out;}
    @Transactional public Map<String,Object> put(AuthService.Identity actor,String tenant,String key,NotificationInputs.ChannelPolicy in,String request,ScopeFilter.Selection selection){auth.lockRequest(actor,tenant,NotificationPolicy.CONFIG_RIGHTS);tenants.lockEnabledRevision(tenant);idem.validateKey(key);String selected=NotificationPolicy.choice(in.scopeType(),List.of("UNIT","PLACE"));String place=in.placeId();if(selected.equals("UNIT")){if(place!=null)throw ApiError.bad("单位策略不能指定位置");}else{place=NotificationPolicy.id(place);if(jdbc.queryForList("SELECT id FROM places WHERE tenant_id=? AND id=? FOR UPDATE",tenant,place).isEmpty())throw ApiError.missing();}requireVisible(actor.user().id(),tenant,selected,place,selection);if(in.smsEnabled()!=null)NotificationPolicy.flag(in.smsEnabled());if(in.voiceEnabled()!=null)NotificationPolicy.flag(in.voiceEnabled());if(in.wechatEnabled()!=null)NotificationPolicy.flag(in.wechatEnabled());NotificationPolicy.text(in.reason(),Limits.NOTIFICATION_REASON_MAX);String target=selected.equals("UNIT")?tenant:place;var found=jdbc.queryForList("SELECT * FROM notification_channel_policies WHERE tenant_id=? AND scope_type=? AND scope_key=? FOR UPDATE",tenant,selected,target);long revision=found.isEmpty()?0:number(found.getFirst(),"revision");NotificationPolicy.revision(in.expectedRevision(),revision);if(revision==Long.MAX_VALUE)throw ApiError.conflict("REVISION_EXHAUSTED","策略revision已达上限");String hash=idem.fingerprint(Arrays.asList(tenant,selected,place,in.smsEnabled(),in.voiceEnabled(),in.wechatEnabled(),in.expectedRevision(),in.reason()));var replay=idem.replay(actor.user().id(),"notification-channel-policy",key,hash,NotificationConfigCommands.Reference.class);if(replay!=null)return read(actor.user().id(),tenant,selected,place,selection);if(in.smsEnabled()==null&&in.voiceEnabled()==null&&in.wechatEnabled()==null){if(!found.isEmpty())jdbc.update("DELETE FROM notification_channel_policies WHERE id=?",found.getFirst().get("id"));}else if(found.isEmpty()){jdbc.update("INSERT INTO notification_channel_policies(id,tenant_id,scope_type,scope_key,place_id,sms_enabled,voice_enabled,wechat_enabled,revision,changed_at) VALUES (?,?,?,?,?,?,?,?,1,?)",UUID.randomUUID().toString(),tenant,selected,target,place,in.smsEnabled(),in.voiceEnabled(),in.wechatEnabled(),time.now());}else{jdbc.update("UPDATE notification_channel_policies SET sms_enabled=?,voice_enabled=?,wechat_enabled=?,revision=revision+1,changed_at=? WHERE id=? AND revision=?",in.smsEnabled(),in.voiceEnabled(),in.wechatEnabled(),time.now(),found.getFirst().get("id"),revision);}idem.save(actor.user().id(),"notification-channel-policy",key,hash,new NotificationConfigCommands.Reference(target));audit.record(actor.user().id(),tenant,"NOTIFICATION_RULE_WRITE",target,"SUCCESS",request);return read(actor.user().id(),tenant,selected,place,selection);}
    /** Names the scope that supplied the effective value; DEFAULT means no explicit policy anywhere. */
    private Map<String,Object> source(String tenant,Effective resolved){if(resolved.scopeId()==null)return null;var out=new LinkedHashMap<String,Object>();out.put("scope_type",resolved.scopeType());out.put("scope_id",resolved.scopeId());out.put("name",resolved.scopeType().equals("UNIT")?jdbc.queryForObject("SELECT name FROM tenants WHERE id=?",String.class,resolved.scopeId()):jdbc.queryForObject("SELECT name FROM places WHERE tenant_id=? AND id=?",String.class,tenant,resolved.scopeId()));return out;}
    private void requireVisible(String actor,String tenant,String scopeType,String place,ScopeFilter.Selection selection){if(selection.empty())throw ApiError.missing();if(scopeType.equals("UNIT")){var unit=scope.units(actor,"t","id",tenant,selection);if(jdbc.queryForList("SELECT t.id FROM tenants t WHERE t.id=?"+unit.and(),concat(List.of(tenant),unit.bindings()).toArray()).isEmpty())throw ApiError.missing();return;}var access=scope.units(actor,"p","tenant_id",tenant,ScopeFilter.Selection.all());if(jdbc.queryForList("SELECT p.id FROM places p WHERE p.tenant_id=? AND p.id=?"+access.and(),concat(List.of(tenant,place),access.bindings()).toArray()).isEmpty())throw ApiError.missing();if(selection.tenantIds().isEmpty()&&selection.placeIds().isEmpty())return;if(selection.tenantIds().contains(tenant))return;String current=place;var seen=new HashSet<String>();while(current!=null&&seen.add(current)){if(selection.placeIds().contains(current))return;var parents=jdbc.queryForList("SELECT parent_place_id FROM places WHERE tenant_id=? AND id=?",tenant,current);if(parents.isEmpty())break;current=(String)parents.getFirst().get("parent_place_id");}throw ApiError.missing();}
}
